"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3229],{35427:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldController","desc":"Discovers shield-console instances via CollectionService tags and wires their\\nProximityPrompt to send `ReqRechargeShield` (mirroring TrainClient\'s refuel\\nprompt, including the \\"hold with no energy\\" early-out). On a successful\\nrecharge it plays a SoundManager SFX. Incoming `TrainShieldSync` packets are\\nalso bridged into `Signals.OnTrainShieldChanged`, which\\n`TrainShieldGuiController` uses as the edge trigger for the monitor\'s\\ncapacity readout. Each incoming snapshot is written to `TrainStateCache`\\nbefore that signal fires, so a late subscriber can still recover it.\\n\\nThis controller owns only the Energy-recharge prompt\\n(`TrainConfig.SHIELD_PROMPT_PART_NAME`). The console\'s second prompt, which\\nopens the full-screen readout, belongs to `TrainShieldGuiController`.","realm":["Client"],"source":{"line":20,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldController.client.luau"}}')}}]);